typedef float rational_t;
typedef float fp;

extern "C" float sqrtf(float);
#define assert(condition) ((void)0)

const rational_t SMALL_DIST = 0.00001f;

inline fp fast_recip_sqrt(fp x)
{
  return 1.0F/(rational_t)sqrtf(x);
}

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }

  inline vector3d& operator = (const vector3d& v)
  { x = v.x; y = v.y; z = v.z; return *this; }

  inline vector3d& operator *= (T d)
  { x *= d; y *= d; z *= d; return *this; }

  inline T length2() const
  { return x*x + y*y + z*z; }

  inline vector3d& normalize()
  {
    T l2 = length2();
    if (l2>SMALL_DIST*SMALL_DIST)
      *this *= fast_recip_sqrt(l2);
    return *this;
  }
};

inline vector3d operator + (const vector3d& a, const vector3d& b)
{ return vector3d(a.x + b.x, a.y + b.y, a.z + b.z); }

inline vector3d operator * (const vector3d& a, vector3d::T d)
{ return vector3d(d * a.x, d * a.y, d * a.z); }

void interpolate_vector(vector3d *new_vector, vector3d first_vector, vector3d second_vector, float difference, int curve)
{
  assert(difference >= 0.0f && difference <= 1.0f);

  if (curve == 1)
    difference = 3*difference*difference- 2*difference*difference*difference;
  else if (curve == 2)
    difference *= difference;
  else if (curve == 3)
    difference = (2*difference) - (difference*difference);

  *new_vector = (first_vector * (1-difference)) + (second_vector * difference);

  if (curve != 4)
    new_vector->normalize();
}
